export type NonEmptyStack<T> = {
    item: T;
    rest: Stack<T>;
};
export type Stack<T> = null | NonEmptyStack<T>;
export declare function empty<T>(): Stack<T>;
export declare function push<T>(item: T, rest: Stack<T>): NonEmptyStack<T>;
export declare function isEmpty<T>(s: Stack<T>): s is null;
export declare function nonEmpty<T>(s: Stack<T>): s is NonEmptyStack<T>;
export declare function rest<T>(s: Stack<T>): Stack<T>;
export declare function drop<T>(s: Stack<T>, n: number): Stack<T>;
export declare function dropNonEmpty<T>(s: NonEmptyStack<T>, n: number): NonEmptyStack<T>;
export declare function depth<T>(s: Stack<T>): number;
export declare function toArray<T>(s: Stack<T>): T[];
